$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json")) {
  throw "Execute este script na pasta raiz do SaborFlow."
}

Write-Host "=== ETAPA 13.13 - ALERTAS DE ANOMALIAS ==="

Write-Host "Aplicando: lib/security/anomaly-alerts.ts"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "lib\security\anomaly-alerts.ts"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) {
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
}
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Aplicando: app/api/internal/security/anomaly-scan/route.ts"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "app\api\internal\security\anomaly-scan\route.ts"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) {
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
}
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Aplicando: app/api/superadmin/security-alerts/route.ts"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "app\api\superadmin\security-alerts\route.ts"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) {
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
}
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Verificando diff..."
git diff --check
if ($LASTEXITCODE -ne 0) {
  throw "git diff --check encontrou problema."
}

Write-Host "Executando typecheck..."
npm.cmd run typecheck
$typeExit = $LASTEXITCODE
if ($typeExit -ne 0) {
  git restore -- next-env.d.ts 2>$null
  throw "TYPECHECK FALHOU. Envie apenas o erro final."
}

Write-Host "Executando build..."
npm.cmd run build
$buildExit = $LASTEXITCODE
git restore -- next-env.d.ts 2>$null
if ($buildExit -ne 0) {
  throw "BUILD FALHOU. Envie apenas o erro final."
}

Write-Host ""
Write-Host "=============================================="
Write-Host "ETAPA 13.13 PREPARADA - BUILD APROVADO"
Write-Host "=============================================="
Write-Host "- scanner de anomalias criado"
Write-Host "- monitora rate limit, tempestade de sessoes e alteracoes sensiveis"
Write-Host "- alertas persistem na sf_audit_log da Etapa 13.12"
Write-Host "- deduplicacao e cooldown evitam spam"
Write-Host "- notificacao usa o Resend ja configurado no SaborFlow"
Write-Host "- destinatarios owner do Superadmin + SECURITY_ALERT_EMAIL_TO opcional"
Write-Host "- rota interna exige SECURITY_ALERTS_CRON_TOKEN"
Write-Host "- Superadmin pode consultar e executar scan manual"
Write-Host "- nenhuma migration nova e necessaria"
Write-Host "- ainda nao foi feito commit nem deploy"
